import json, os, time, uuid
BOOT = uuid.uuid4().hex
print('FUNCTION_INIT ' + BOOT, flush=True)
def handler(event, context):
    path = '/tmp/extension-probe-counter'
    try:
        with open(path) as f: count = int(f.read()) + 1
    except FileNotFoundError:
        count = 1
    with open(path, 'w') as f: f.write(str(count))
    started = time.monotonic_ns()
    print('FUNCTION_START ' + context.aws_request_id, flush=True)
    if event.get('sleep'):
        time.sleep(event['sleep'])
    print('FUNCTION_END ' + context.aws_request_id, flush=True)
    return {'boot': BOOT, 'counter': count, 'request_id': context.aws_request_id,
            'started_monotonic_ns': started, 'returned_monotonic_ns': time.monotonic_ns(),
            'pid': os.getpid(), 'version': context.function_version}
